sp_header_footer.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_header_footer.css:
.custom-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: #fffEFA; /* White background */
  color: #000000; /* Black text */
  padding: 10px 20px;
  font-family: 'Segoe UI', sans-serif;
  border-bottom: 1px solid #ccc; /* Optional: subtle bottom border */
}

.header-left h2 {
  margin: 0;
  font-size: 20px;
  color: #000000; /* Ensure heading is black */
}

.header-right {
  display: flex;
  align-items: center;
  gap: 20px;
}

.header-right a {
  color: #000000; /* Black links */
  text-decoration: none;
  font-weight: 500;
}

.header-right a:hover {
  text-decoration: underline;
  color: #333333; /* Slightly darker on hover */
}

.profile {
  display: flex;
  align-items: center;
  gap: 10px;
}

.profile img {
  width: 30px;
  height: 30px;
  border-radius: 50%;
}
